 /// Parte C++ della primitiva vcenew()
 extern "C" bool c_vcenew()
 {
-/// @todo Scrivere il corpo della primitiva vcenew()
-// ( SOLUZIONE 2025-01-27
-//   SOLUZIONE 2025-01-27 )
+	natl pid = getpid();
+	sem_wait(ce.mutex);
+	// il processo non deve già avere una VCE
+	if (ce.vces[pid] != nullptr) {
+		flog(LOG_WARN, "vcenew: il processo ha gia' una VCE");
+		sem_signal(ce.mutex);
+		abort_p();
+		return false;
+	}
+	vce_des *v = new vce_des;
+	if (!v) {
+		flog(LOG_WARN, "vcenew: impossibile allocare VCE");
+		sem_signal(ce.mutex);
+		return false;
+	}
+	if (!vce_des_init(v)) {
+		delete v;
+		sem_signal(ce.mutex);
+		return false;
+	}
+	ce.vces[pid] = v;
+	sem_signal(ce.mutex);
+	return true;
 }

 /// Parte C++ della primitiva vcewrite()
@@ -814,11 +834,55 @@ extern "C" void c_vcewrite(char c)
 /// Processo esterno associato alla periferica CE
 extern "C" void estern_ce(natq)
 {
-/// @todo Scrivere il corpo del processo esterno
-// ( SOLUZIONE 2025-01-27
-//   SOLUZIONE 2025-01-27 )
+	natl last_served = 0;
+	natq ev;
+	for (;;) {
+		ev = evget();
+		sem_wait(ce.mutex);
+		if (ev == 0) {
+			// interruzione: trasmissione completata
+			ce.busy = false;
+		} else if (ev != 0xFFFFFFFF) {
+			// notifica di terminazione: ev contiene il pid del processo terminato
+			vce_des *v = ce.vces[ev];
+			if (v) {
+				v->terminated = true;
+				// se la VCE è vuota, la deallochiamo subito
+				if (v->n == 0) {
+					ce.vces[ev] = nullptr;
+					delete v;
+				}
+			}
+		}
+		// se la periferica è libera e ci sono byte in attesa, iniziamo una trasmissione
+		if (!ce.busy) {
+			vce_des *v = vce_des_next(last_served);
+			if (v) {
+				natl c = vce_des_read(v);
+				if (c != 0xFFFFFFFF) {
+					outputb((char)c, ce.iTBR);
+					ce.busy = true;
+				}
+				// se la VCE è ora vuota e il proprietario è terminato, la deallochiamo
+				if (v->n == 0 && v->terminated) {
+					for (natl i = 0; i < MAX_PROC; i++) {
+						if (ce.vces[i] == v) {
+							ce.vces[i] = nullptr;
+							delete v;
+							break;
+						}
+					}
+				}
+				if (v->waiting) {
+					v->waiting = false;
+					sem_signal(v->sync);
+				}
+			}
+		}
+		sem_signal(ce.mutex);
+		wfi();
+	}
 }
